/**
 * FEATURE: The website's photo files (Mt. Hood hero photos) and their credits.
 * COVERS:  assets/img/photos/* (generated by scripts/images/build-photos.js), assets/img/photos/CREDITS.md
 * WHY:     Pages reference these files by exact name and they must stay small enough to load fast.
 *          A missing, huge, or wrongly sized file would break or slow every page that uses it.
 * UPDATE WHEN: photos are added, renamed, or resized in scripts/images/build-photos.js.
 * REMOVE WHEN: the site stops using local photos.
 */
const fs = require('fs');
const path = require('path');
const sharp = require('sharp');
const { test, expect } = require('./support/fixtures');

test.skip(({ isMobile }) => isMobile, 'No browser needed; runs once in the desktop project.');

const dir = path.resolve(__dirname, '..', 'assets', 'img', 'photos');
const expected = [];
for (const name of ['hood-sunset', 'trillium']) {
  for (const w of [960, 1600, 2400]) expected.push(`${name}-${w}.webp`);
  expected.push(`${name}-1600.jpg`);
}

test('every photo file exists, is non-empty, and is under 450 KB', () => {
  for (const file of expected) {
    const p = path.join(dir, file);
    expect(fs.existsSync(p), `${file} should exist`).toBe(true);
    const size = fs.statSync(p).size;
    expect(size, `${file} should not be empty`).toBeGreaterThan(0);
    expect(size, `${file} should be under 450 KB`).toBeLessThan(450 * 1024);
  }
});

test('photo widths match their file names and aspect ratios are right', async () => {
  for (const file of expected) {
    const width = Number(file.match(/-(\d+)\./)[1]);
    const meta = await sharp(path.join(dir, file)).metadata();
    expect(meta.width, `${file} width`).toBe(width);
    const ratio = file.startsWith('hood-sunset') ? 3 / 2 : 16 / 9;
    expect(meta.width / meta.height, `${file} aspect ratio`).toBeCloseTo(ratio, 1);
  }
});

test('CREDITS.md names both Pexels photos and the photographer', () => {
  const text = fs.readFileSync(path.join(dir, 'CREDITS.md'), 'utf8');
  expect(text).toContain('pexels.com/photo/3493805');
  expect(text).toContain('pexels.com/photo/3551192');
  expect(text).toContain('Aleksey Kuprikov');
});
